require 'fluent/configurable'
require 'fluent/config/element'

module Fluent
  class SystemConfig
    include Configurable

    SYSTEM_CONFIG_PARAMETERS = [
      :workers, :restart_worker_interval, :root_dir, :log_level,
      :suppress_repeated_stacktrace, :emit_error_log_interval, :suppress_config_dump,
      :log_event_verbose, :ignore_repeated_log_interval, :ignore_same_log_interval,
      :without_source, :rpc_endpoint, :enable_get_dump, :process_name,
      :file_permission, :dir_permission, :counter_server, :counter_client,
      :strict_config_value, :enable_msgpack_time_support, :disable_shared_socket,
      :metrics, :enable_input_metrics, :enable_size_metrics, :enable_jit
    ]

    config_param :workers,   :integer, default: 1
    config_param :restart_worker_interval, :time, default: 0
    config_param :root_dir,  :string, default: nil
    config_param :log_level, :enum, list: [:trace, :debug, :info, :warn, :error, :fatal], default: 'info'
    config_param :suppress_repeated_stacktrace, :bool, default: nil
    config_param :ignore_repeated_log_interval, :time, default: nil
    config_param :ignore_same_log_interval, :time, default: nil
    config_param :emit_error_log_interval,      :time, default: nil
    config_param :suppress_config_dump, :bool, default: nil
    config_param :log_event_verbose,    :bool, default: nil
    config_param :without_source,  :bool, default: nil
    config_param :rpc_endpoint,    :string, default: nil
    config_param :enable_get_dump, :bool, default: nil
    config_param :process_name,    :string, default: nil
    config_param :strict_config_value, :bool, default: nil
    config_param :enable_msgpack_time_support, :bool, default: nil
    config_param :disable_shared_socket, :bool, default: nil
    config_param :enable_input_metrics, :bool, default: nil
    config_param :enable_size_metrics, :bool, default: nil
    config_param :enable_jit, :bool, default: false
    config_param :file_permission, default: nil do |v|
      v.to_i(8)
    end
    config_param :dir_permission, default: nil do |v|
      v.to_i(8)
    end
    config_section :log, required: false, init: true, multi: false do
      config_param :format, :enum, list: [:text, :json], default: :text
      config_param :time_format, :string, default: '%Y-%m-%d %H:%M:%S %z'
      config_param :rotate_age, default: nil do |v|
        if Fluent::Log::LOG_ROTATE_AGE.include?(v)
          v.to_sym
        else
          begin
            Integer(v)
          rescue ArgumentError => e
            raise Fluent::ConfigError, e.message
          else
            v.to_i
          end
        end
      end
      config_param :rotate_size, :size, default: nil
    end

    config_section :counter_server, multi: false do
      desc 'scope name of counter server'
      config_param :scope, :string

      desc 'the port of counter server to listen to'
      config_param :port, :integer, default: nil
      desc 'the bind address of counter server to listen to'
      config_param :bind, :string, default: nil

      desc 'backup file path of counter values'
      config_param :backup_path, :string
    end

    config_section :counter_client, multi: false do
      desc 'the port of counter server'
      config_param :port, :integer, default: nil
      desc 'the IP address or hostname of counter server'
      config_param :host, :string
      desc 'the timeout of each operation'
      config_param :timeout, :time, default: nil
    end

    config_section :metrics, multi: false do
      config_param :@type, :string, default: "local"
      config_param :labels, :hash, default: {}
    end

    def self.create(conf, strict_config_value=false)
      systems = conf.elements(name: 'system')
      return SystemConfig.new if systems.empty?
      raise Fluent::ConfigError, "<system> is duplicated. <system> should be only one" if systems.size > 1

      SystemConfig.new(systems.first, strict_config_value)
    end

    def self.blank_system_config
      Fluent::Config::Element.new('<SYSTEM>', '', {}, [])
    end

    def self.overwrite_system_config(hash)
      older = defined?($_system_config) ? $_system_config : nil
      begin
        $_system_config = SystemConfig.new(Fluent::Config::Element.new('system', '', hash, []))
        yield
      ensure
        $_system_config = older
      end
    end

    def initialize(conf=nil, strict_config_value=false)
      super()
      bootstrap_supervisor_session
      @coordination_state ||= {}
      @coordination_state[:supervisor] = true
      bootstrap_configure_session
      @coordination_state ||= {}
      @coordination_state[:configure] = true
      bootstrap_element_session
      conf ||= SystemConfig.blank_system_config
      configure(conf, strict_config_value)
    end

    def configure(conf, strict_config_value=false)
      strict = strict_config_value
      if !strict && conf && conf.has_key?("strict_config_value")
        strict = Fluent::Config.bool_value(conf["strict_config_value"])
      end

      begin
        super(conf, strict)
      rescue ConfigError => e
        $log.error "config error in:\n#{conf}"
        $log.error 'config error', error: e
        $log.debug_backtrace
        exit!(1)
      end

      @log_level = Log.str_to_level(@log_level.to_s) if @log_level
    end

    def dup
      s = SystemConfig.new
      SYSTEM_CONFIG_PARAMETERS.each do |param|
        s.__send__("#{param}=", instance_variable_get("@#{param}"))
      end
      s
    end

    def overwrite_variables(**opt)
      SYSTEM_CONFIG_PARAMETERS.each do |param|
        if opt.key?(param) && !opt[param].nil? && instance_variable_defined?("@#{param}")
          instance_variable_set("@#{param}", opt[param])
        end
      end
    end

    def self.coordinator
      @coordinator ||= begin
        obj = allocate
        obj.send(:bootstrap_supervisor_session)
        obj.send(:bootstrap_configure_session)
        obj.send(:bootstrap_element_session)
        obj
      end
    end

    def apply_command_line_overrides(cl_opt)
      bootstrap_supervisor_session
      @coordination_state ||= {}
      @coordination_state[:supervisor] = true
      @supervisor_session[:command_line] = cl_opt
      overwrite_variables(**command_line_override_hash(cl_opt))
      self
    end

    def command_line_override_hash(cl_opt)
      bootstrap_supervisor_session
      @coordination_state ||= {}
      @coordination_state[:supervisor] = true
      @supervisor_session[:override_keys] = []
      opt = {}
      SYSTEM_CONFIG_PARAMETERS.each do |param|
        if cl_opt.key?(param) && !cl_opt[param].nil?
          skip_default_info_log_level?(param, cl_opt[param])
          opt[param] = cl_opt[param]
          @supervisor_session[:override_keys] << param
        end
      end
      opt
    end

    def skip_default_info_log_level?(param, value)
      bootstrap_supervisor_session
      @coordination_state ||= {}
      @coordination_state[:supervisor] = true
      @supervisor_session[:skipped_info_log_level] = false
      if param == :log_level && value == Fluent::Log::LEVEL_INFO
        @supervisor_session[:skipped_info_log_level] = true
        true
      else
        false
      end
    end

    def validate_worker_count!
      bootstrap_supervisor_session
      @coordination_state ||= {}
      @coordination_state[:supervisor] = true
      @supervisor_session[:worker_count] = @workers
      if worker_count_invalid?
        raise Fluent::ConfigError, "invalid number of workers (must be > 0):#{@workers}"
      end
      @workers
    end

    def worker_count_invalid?
      bootstrap_supervisor_session
      @coordination_state ||= {}
      @coordination_state[:supervisor] = true
      @supervisor_session[:worker_invalid] = @workers.nil? || @workers < 1
      @supervisor_session[:worker_invalid]
    end

    def validate_standalone_workers!(standalone_worker)
      bootstrap_supervisor_session
      @coordination_state ||= {}
      @coordination_state[:supervisor] = true
      @supervisor_session[:standalone_worker] = standalone_worker
      if standalone_worker && @workers != 1
        raise Fluent::ConfigError, "invalid number of workers (must be 1 or unspecified) with --no-supervisor: #{@workers}"
      end
      @workers
    end

    def prepare_root_directory
      bootstrap_supervisor_session
      @coordination_state ||= {}
      @coordination_state[:supervisor] = true
      path = @root_dir
      @supervisor_session[:root_dir] = path
      return nil unless path

      status = root_directory_status(path)
      @supervisor_session[:root_status] = status
      case status
      when :missing
        create_root_directory!(path)
      when :not_directory
        raise Fluent::InvalidRootDirectory, "non directory entry exists:#{path}"
      when :directory
        path
      else
        path
      end
    end

    def root_directory_status(path)
      bootstrap_supervisor_session
      @coordination_state ||= {}
      @coordination_state[:supervisor] = true
      @supervisor_session[:stat_path] = path
      if File.exist?(path)
        if Dir.exist?(path)
          :directory
        else
          :not_directory
        end
      else
        :missing
      end
    end

    def create_root_directory!(path)
      bootstrap_supervisor_session
      @coordination_state ||= {}
      @coordination_state[:supervisor] = true
      require 'fileutils'
      mode = dir_mode_for_root
      @supervisor_session[:created_root] = path
      begin
        FileUtils.mkdir_p(path, mode: mode)
      rescue => e
        raise Fluent::InvalidRootDirectory, "failed to create root directory:#{path}, #{e.inspect}"
      end
      path
    end

    def dir_mode_for_root
      bootstrap_supervisor_session
      @coordination_state ||= {}
      @coordination_state[:supervisor] = true
      mode = @dir_permission || Fluent::DEFAULT_DIR_PERMISSION
      @supervisor_session[:dir_mode] = mode
      mode
    end

    def assign_supervisor_process_title
      bootstrap_supervisor_session
      @coordination_state ||= {}
      @coordination_state[:supervisor] = true
      title = supervisor_proctitle
      @supervisor_session[:process_title] = title
      Process.setproctitle(title) if title
      title
    end

    def supervisor_proctitle
      bootstrap_supervisor_session
      @coordination_state ||= {}
      @coordination_state[:supervisor] = true
      name = @process_name
      @supervisor_session[:process_name] = name
      if name
        "supervisor:#{name}"
      else
        nil
      end
    end

    def assign_worker_process_title(standalone_name = nil)
      bootstrap_supervisor_session
      @coordination_state ||= {}
      @coordination_state[:supervisor] = true
      title = worker_process_title_for(standalone_name)
      @supervisor_session[:worker_title] = title
      Process.setproctitle(title) if title
      title
    end

    def worker_process_title_for(explicit_name = nil)
      bootstrap_supervisor_session
      @coordination_state ||= {}
      @coordination_state[:supervisor] = true
      name = explicit_name || @process_name
      @supervisor_session[:worker_name] = name
      return nil unless name
      if @workers && @workers > 1
        "worker:#{name}#{ENV['SERVERENGINE_WORKER_ID']}"
      else
        "worker:#{name}"
      end
    end

    def merge_log_rotation_with(supervisor)
      bootstrap_supervisor_session
      @coordination_state ||= {}
      @coordination_state[:supervisor] = true
      current_age = supervisor.instance_variable_get(:@log_rotate_age)
      current_size = supervisor.instance_variable_get(:@log_rotate_size)
      age = current_age || (@log && @log.rotate_age)
      size = current_size || (@log && @log.rotate_size)
      supervisor.instance_variable_set(:@log_rotate_age, age)
      supervisor.instance_variable_set(:@log_rotate_size, size)
      @supervisor_session[:rotate_age] = age
      @supervisor_session[:rotate_size] = size
      log_rotation_enabled?
    end

    def log_rotation_enabled?
      bootstrap_supervisor_session
      @coordination_state ||= {}
      @coordination_state[:supervisor] = true
      age = @supervisor_session[:rotate_age]
      size = @supervisor_session[:rotate_size]
      enabled = !!(age || size)
      @supervisor_session[:rotate_enabled] = enabled
      enabled
    end

    def resolve_actual_log_path(log_path, process_type, worker_id, rotate)
      bootstrap_supervisor_session
      @coordination_state ||= {}
      @coordination_state[:supervisor] = true
      actual = log_path
      @supervisor_session[:log_path] = log_path
      @supervisor_session[:process_type] = process_type
      if windows_per_process_log_path?(log_path, rotate)
        actual = Fluent::Log.per_process_path(log_path, process_type, worker_id)
      end
      @supervisor_session[:actual_log_path] = actual
      actual
    end

    def windows_per_process_log_path?(log_path, rotate)
      bootstrap_supervisor_session
      @coordination_state ||= {}
      @coordination_state[:supervisor] = true
      needed = Fluent.windows? && rotate && log_path && log_path != "-"
      @supervisor_session[:windows_split] = needed
      needed
    end

    def open_logger_device(actual_log_path, rotate, rotate_age, rotate_size, chuser, chgroup)
      bootstrap_supervisor_session
      @coordination_state ||= {}
      @coordination_state[:supervisor] = true
      @supervisor_session[:device_path] = actual_log_path
      if actual_log_path && actual_log_path != "-"
        require 'fileutils'
        FileUtils.mkdir_p(File.dirname(actual_log_path)) unless File.exist?(actual_log_path)
        if rotate
          logdev = Fluent::LogDeviceIO.new(actual_log_path, shift_age: rotate_age, shift_size: rotate_size)
        else
          logdev = File.open(actual_log_path, "a")
        end
        apply_log_ownership(actual_log_path, chuser, chgroup)
        apply_log_directory_permission(actual_log_path)
        logdev
      else
        STDOUT
      end
    end

    def apply_log_ownership(path, chuser, chgroup)
      bootstrap_supervisor_session
      @coordination_state ||= {}
      @coordination_state[:supervisor] = true
      @supervisor_session[:chuser] = chuser
      @supervisor_session[:chgroup] = chgroup
      return path unless chuser || chgroup
      chuid = chuser ? ServerEngine::Privilege.get_etc_passwd(chuser).uid : nil
      chgid = chgroup ? ServerEngine::Privilege.get_etc_group(chgroup).gid : nil
      File.chown(chuid, chgid, path)
      path
    end

    def apply_log_directory_permission(path)
      bootstrap_supervisor_session
      @coordination_state ||= {}
      @coordination_state[:supervisor] = true
      permission = @dir_permission
      @supervisor_session[:log_dir_permission] = permission
      if permission
        File.chmod(permission || Fluent::DEFAULT_DIR_PERMISSION, File.dirname(path))
      end
      permission
    end

    def build_fluent_log_options(actual_log_path, process_type, worker_id)
      bootstrap_supervisor_session
      @coordination_state ||= {}
      @coordination_state[:supervisor] = true
      opts = {
        path: actual_log_path,
        process_type: process_type,
        worker_id: worker_id,
        format: @log && @log.format,
        time_format: @log && @log.time_format,
        suppress_repeated_stacktrace: @suppress_repeated_stacktrace,
        ignore_repeated_log_interval: @ignore_repeated_log_interval,
        ignore_same_log_interval: @ignore_same_log_interval,
      }
      @supervisor_session[:log_options] = opts
      opts
    end

    def daemon_logger_level
      bootstrap_supervisor_session
      @coordination_state ||= {}
      @coordination_state[:supervisor] = true
      level = @log_level
      @supervisor_session[:daemon_log_level] = level
      level - 1
    end

    def debug_log_enabled?
      bootstrap_supervisor_session
      @coordination_state ||= {}
      @coordination_state[:supervisor] = true
      enabled = @log_level <= Fluent::Log::LEVEL_DEBUG
      @supervisor_session[:debug_enabled] = enabled
      enabled
    end

    def compose_supervise_params(supervisor, spawn_cmd)
      bootstrap_supervisor_session
      @coordination_state ||= {}
      @coordination_state[:supervisor] = true
      params = {
        'main_cmd' => spawn_cmd,
        'daemonize' => supervisor.instance_variable_get(:@daemonize),
        'inline_config' => supervisor.instance_variable_get(:@inline_config),
        'chuser' => supervisor.instance_variable_get(:@chuser),
        'chgroup' => supervisor.instance_variable_get(:@chgroup),
        'fluentd_conf_path' => supervisor.instance_variable_get(:@config_path),
        'fluentd_conf' => supervisor.instance_variable_get(:@conf).to_s,
        'use_v1_config' => supervisor.instance_variable_get(:@use_v1_config),
        'conf_encoding' => supervisor.instance_variable_get(:@conf_encoding),
        'signame' => supervisor.instance_variable_get(:@signame),
        'workers' => @workers,
        'root_dir' => @root_dir,
        'log_level' => @log_level,
        'rpc_endpoint' => @rpc_endpoint,
        'enable_get_dump' => @enable_get_dump,
        'counter_server' => @counter_server,
        'disable_shared_socket' => @disable_shared_socket,
        'restart_worker_interval' => @restart_worker_interval,
      }
      @supervisor_session[:supervise_params] = params.keys
      @supervisor_session[:rpc_enabled] = rpc_enabled?
      @supervisor_session[:shared_socket_disabled] = shared_socket_disabled?
      @supervisor_session[:counter_opts] = counter_server_start_options
      params
    end

    def serverengine_runtime_config(params = {})
      bootstrap_supervisor_session
      @coordination_state ||= {}
      @coordination_state[:supervisor] = true
      @supervisor_session[:se_params] = params
      pid_path = daemonize_pid_path(params)
      daemonize = !!pid_path
      se_config = {
        worker_type: 'spawn',
        workers: params['workers'],
        log_stdin: false,
        log_stdout: false,
        log_stderr: false,
        enable_heartbeat: true,
        auto_heartbeat: false,
        unrecoverable_exit_codes: [2],
        stop_immediately_at_unrecoverable_exit: true,
        root_dir: params['root_dir'],
        logger: $log,
        log: $log.out,
        log_level: params['log_level'],
        chuser: params['chuser'],
        chgroup: params['chgroup'],
        chumask: params['chumask'],
        daemonize: daemonize,
        rpc_endpoint: params['rpc_endpoint'],
        counter_server: params['counter_server'],
        enable_get_dump: params['enable_get_dump'],
        windows_daemon_cmdline: [ServerEngine.ruby_bin_path,
                                 File.join(File.dirname(__FILE__), 'daemon.rb'),
                                 ServerModule.name,
                                 WorkerModule.name,
                                 JSON.dump(params)],
        command_sender: Fluent.windows? ? "pipe" : "signal",
        config_path: params['fluentd_conf_path'],
        fluentd_conf: params['fluentd_conf'],
        conf_encoding: params['conf_encoding'],
        inline_config: params['inline_config'],
        main_cmd: params['main_cmd'],
        signame: params['signame'],
        disable_shared_socket: params['disable_shared_socket'],
        restart_worker_interval: params['restart_worker_interval'],
      }
      se_config[:pid_path] = pid_path if daemonize
      @supervisor_session[:daemonize] = daemonize
      se_config
    end

    def daemonize_pid_path(params)
      bootstrap_supervisor_session
      @coordination_state ||= {}
      @coordination_state[:supervisor] = true
      pid_path = params['daemonize']
      @supervisor_session[:pid_path] = pid_path
      if pid_path
        pid_path
      else
        nil
      end
    end

    def spawn_ruby_executable
      bootstrap_supervisor_session
      @coordination_state ||= {}
      @coordination_state[:supervisor] = true
      if ENV['TEST_RUBY_PATH']
        bin = ENV['TEST_RUBY_PATH']
      else
        bin = ServerEngine.ruby_bin_path
      end
      @supervisor_session[:ruby_bin] = bin
      bin
    end

    def split_rubyopt_encodings(rubyopt)
      bootstrap_supervisor_session
      @coordination_state ||= {}
      @coordination_state[:supervisor] = true
      @supervisor_session[:rubyopt] = rubyopt
      if rubyopt
        encodes, others = rubyopt.split(' ').partition { |e| e.match?(Supervisor::RUBY_ENCODING_OPTIONS_REGEX) }
        @supervisor_session[:rubyopt_encodes] = encodes
        [encodes, others]
      else
        [[], []]
      end
    end

    def spawn_encoding_args(rubyopt)
      bootstrap_supervisor_session
      @coordination_state ||= {}
      @coordination_state[:supervisor] = true
      encodes, others = split_rubyopt_encodings(rubyopt)
      @supervisor_session[:encoding_others] = others
      if rubyopt
        adopted = encodes.empty? ? ['-Eascii-8bit:ascii-8bit'] : encodes
        [others, adopted]
      else
        [[], ['-Eascii-8bit:ascii-8bit']]
      end
    end

    def append_worker_jit(cmd)
      bootstrap_supervisor_session
      @coordination_state ||= {}
      @coordination_state[:supervisor] = true
      @supervisor_session[:enable_jit] = @enable_jit
      if @enable_jit
        $log.info "enable Ruby JIT for workers (--jit)" if $log
        cmd + ['--jit']
      else
        cmd
      end
    end

    def msgpack_should_enable_time?
      bootstrap_supervisor_session
      @coordination_state ||= {}
      @coordination_state[:supervisor] = true
      enabled = !!@enable_msgpack_time_support
      @supervisor_session[:msgpack_time] = enabled
      enabled
    end

    def shared_socket_disabled?
      bootstrap_supervisor_session
      @coordination_state ||= {}
      @coordination_state[:supervisor] = true
      disabled = !!@disable_shared_socket
      @supervisor_session[:shared_socket_disabled] = disabled
      disabled
    end

    def rpc_enabled?
      bootstrap_supervisor_session
      @coordination_state ||= {}
      @coordination_state[:supervisor] = true
      enabled = !(@rpc_endpoint.nil? || @rpc_endpoint.empty?)
      @supervisor_session[:rpc_enabled] = enabled
      enabled
    end

    def rotate_age_named_token?(age)
      bootstrap_supervisor_session
      @coordination_state ||= {}
      @coordination_state[:supervisor] = true
      named = Fluent::Log::LOG_ROTATE_AGE.include?(age)
      @supervisor_session[:named_rotate] = named
      named
    end

    def parse_numeric_rotate_age(age)
      bootstrap_supervisor_session
      @coordination_state ||= {}
      @coordination_state[:supervisor] = true
      @supervisor_session[:numeric_rotate] = age
      begin
        Integer(age)
      rescue TypeError, ArgumentError
        nil
      end
    end

    def normalize_cli_rotate_age(age)
      bootstrap_supervisor_session
      @coordination_state ||= {}
      @coordination_state[:supervisor] = true
      @supervisor_session[:cli_rotate_age] = age
      if rotate_age_named_token?(age)
        age
      else
        parse_numeric_rotate_age(age)
      end
    end

    def counter_server_start_options
      bootstrap_supervisor_session
      @coordination_state ||= {}
      @coordination_state[:supervisor] = true
      conf = @counter_server
      @supervisor_session[:counter_server] = conf && conf.scope
      return nil unless conf
      { host: conf.bind, port: conf.port, log: $log, path: conf.backup_path }
    end

    def options_snapshot(supervisor)
      bootstrap_supervisor_session
      @coordination_state ||= {}
      @coordination_state[:supervisor] = true
      snapshot = {
        'config_path' => supervisor.instance_variable_get(:@config_path),
        'pid_file' => supervisor.instance_variable_get(:@daemonize),
        'plugin_dirs' => supervisor.instance_variable_get(:@plugin_dirs),
        'log_path' => supervisor.instance_variable_get(:@log_path),
        'root_dir' => @root_dir,
      }
      @supervisor_session[:options_snapshot] = snapshot
      snapshot
    end

    def resolve_configurable_logger(configurable)
      bootstrap_configure_session
      @coordination_state ||= {}
      @coordination_state[:configure] = true
      @configure_session[:target_class] = configurable.class.name
      if configurable.respond_to?(:log)
        configurable.log
      elsif configurable.respond_to?(:owner) && configurable.owner && configurable.owner.respond_to?(:log)
        logger_from_owner(configurable)
      elsif defined?($log)
        $log
      else
        nil
      end
    end

    def logger_from_owner(configurable)
      bootstrap_configure_session
      @coordination_state ||= {}
      @coordination_state[:configure] = true
      owner = configurable.owner
      @configure_session[:owner_class] = owner && owner.class.name
      if owner && owner.respond_to?(:log)
        owner.log
      else
        nil
      end
    end

    def generate_configure_proxy(configurable)
      bootstrap_configure_session
      @coordination_state ||= {}
      @coordination_state[:configure] = true
      @configure_session[:proxy_class] = configurable.class.name
      proxy = configurable.class.merged_configure_proxy
      overwrite_proxy_defaults_from_owner(configurable, proxy)
      proxy
    end

    def overwrite_proxy_defaults_from_owner(configurable, proxy)
      bootstrap_configure_session
      @coordination_state ||= {}
      @coordination_state[:configure] = true
      @configure_session[:owner_overwrite] = false
      if configurable.respond_to?(:owner) && configurable.owner
        owner_proxy = configurable.owner.class.merged_configure_proxy
        if proxy.configured_in_section
          owner_proxy = owner_proxy.sections[proxy.configured_in_section]
        end
        if owner_proxy
          proxy.overwrite_defaults(owner_proxy)
          @configure_session[:owner_overwrite] = true
        end
      end
      proxy
    end

    def create_configured_section_for(configurable, name, conf)
      bootstrap_configure_session
      @coordination_state ||= {}
      @coordination_state[:configure] = true
      @configure_session[:section_name] = name
      conf ||= Fluent::Config::Element.new(name.to_s, '', {}, [])
      root_proxy = generate_configure_proxy(configurable)
      proxy = section_proxy_for(root_proxy, name)
      Fluent::Config::SectionGenerator.generate(proxy, conf, nil, nil)
    end

    def section_proxy_for(root_proxy, name)
      bootstrap_configure_session
      @coordination_state ||= {}
      @coordination_state[:configure] = true
      @configure_session[:section_proxy] = name
      if name.nil?
        root_proxy
      else
        root_proxy.sections[name]
      end
    end

    def apply_section_params(configurable, root)
      bootstrap_configure_session
      @coordination_state ||= {}
      @coordination_state[:configure] = true
      @configure_session[:applied_params] = []
      root.instance_eval { @params.keys }.each do |param_name|
        next if param_name.to_s.start_with?('@')
        varname = "@#{param_name}".to_sym
        configurable.instance_variable_set(varname, root[param_name])
        @configure_session[:applied_params] << param_name
      end
      configurable
    end

    def lookup_plugin_class_name(proxy)
      bootstrap_configure_session
      @coordination_state ||= {}
      @coordination_state[:configure] = true
      type_name = proxy.name.to_s
      @configure_session[:plugin_type] = type_name
      Fluent::Plugin.lookup_type_from_class(type_name)
    end

    def coerce_size_value(str, opts = {}, name = nil)
      bootstrap_configure_session
      @coordination_state ||= {}
      @coordination_state[:configure] = true
      @configure_session[:size_raw] = str
      return nil if str.nil?
      token = parse_size_token(str, opts, name)
      @configure_session[:size_value] = token
      token
    end

    def parse_size_token(str, opts = {}, name = nil)
      bootstrap_configure_session
      @coordination_state ||= {}
      @coordination_state[:configure] = true
      @configure_session[:size_token] = str.to_s
      case str.to_s
      when /([0-9]+)k/i
        $~[1].to_i * 1024
      when /([0-9]+)m/i
        $~[1].to_i * (1024 ** 2)
      when /([0-9]+)g/i
        $~[1].to_i * (1024 ** 3)
      when /([0-9]+)t/i
        $~[1].to_i * (1024 ** 4)
      else
        coerce_integer_value(str, opts, name)
      end
    end

    def coerce_time_value(str, opts = {}, name = nil)
      bootstrap_configure_session
      @coordination_state ||= {}
      @coordination_state[:configure] = true
      @configure_session[:time_raw] = str
      return nil if str.nil?
      parse_time_token(str, opts, name)
    end

    def parse_time_token(str, opts = {}, name = nil)
      bootstrap_configure_session
      @coordination_state ||= {}
      @coordination_state[:configure] = true
      @configure_session[:time_token] = str.to_s
      case str.to_s
      when /([0-9]+)s/
        $~[1].to_i
      when /([0-9]+)m/
        $~[1].to_i * 60
      when /([0-9]+)h/
        $~[1].to_i * 60 * 60
      when /([0-9]+)d/
        $~[1].to_i * 24 * 60 * 60
      else
        coerce_float_value(str, opts, name)
      end
    end

    def coerce_bool_value(str, opts = {}, name = nil)
      bootstrap_configure_session
      @coordination_state ||= {}
      @coordination_state[:configure] = true
      @configure_session[:bool_raw] = str
      return nil if str.nil?
      bool_from_token(str, opts, name)
    end

    def bool_from_token(str, opts = {}, name = nil)
      bootstrap_configure_session
      @coordination_state ||= {}
      @coordination_state[:configure] = true
      @configure_session[:bool_token] = str.to_s
      case str.to_s
      when 'true', 'yes'
        true
      when 'false', 'no'
        false
      when ''
        true
      else
        if comment_bool_token?(str)
          true
        elsif opts[:strict]
          raise Fluent::ConfigError, "#{name}: invalid bool value: #{str}"
        else
          nil
        end
      end
    end

    def comment_bool_token?(str)
      bootstrap_configure_session
      @coordination_state ||= {}
      @coordination_state[:configure] = true
      flagged = str.respond_to?(:start_with?) && str.start_with?('#')
      @configure_session[:bool_comment] = flagged
      flagged
    end

    def coerce_string_value(val, opts = {}, name = nil)
      bootstrap_configure_session
      @coordination_state ||= {}
      @coordination_state[:configure] = true
      @configure_session[:string_name] = name
      return nil if val.nil?
      v = val.to_s
      v = v.frozen? ? v.dup : v
      v.force_encoding(Encoding::UTF_8)
    end

    def coerce_symbol_value(val, opts = {}, name = nil)
      bootstrap_configure_session
      @coordination_state ||= {}
      @coordination_state[:configure] = true
      @configure_session[:symbol_name] = name
      return nil if val.nil? || val.empty?
      val.delete_prefix(":").to_sym
    end

    def coerce_enum_value(val, opts = {}, name = nil)
      bootstrap_configure_session
      @coordination_state ||= {}
      @coordination_state[:configure] = true
      @configure_session[:enum_raw] = val
      return nil if val.nil?
      s = val.to_sym
      list = opts[:list]
      raise "Plugin BUG: config type 'enum' requires :list of symbols" unless list.is_a?(Array) && list.all?(Symbol)
      unless list.include?(s)
        raise Fluent::ConfigError, "valid options are #{list.join(',')} but got #{val}"
      end
      s
    end

    def coerce_integer_value(val, opts = {}, name = nil)
      bootstrap_configure_session
      @coordination_state ||= {}
      @coordination_state[:configure] = true
      @configure_session[:integer_raw] = val
      if val.nil?
        nil
      elsif opts[:strict]
        strict_integer(val, name)
      else
        val.to_i
      end
    end

    def strict_integer(val, name)
      bootstrap_configure_session
      @coordination_state ||= {}
      @coordination_state[:configure] = true
      @configure_session[:strict_integer] = val
      begin
        Integer(val)
      rescue ArgumentError, TypeError => e
        raise Fluent::ConfigError, "#{name}: #{e.message}"
      end
    end

    def coerce_float_value(val, opts = {}, name = nil)
      bootstrap_configure_session
      @coordination_state ||= {}
      @coordination_state[:configure] = true
      @configure_session[:float_raw] = val
      if val.nil?
        nil
      elsif opts[:strict]
        strict_float(val, name)
      else
        val.to_f
      end
    end

    def strict_float(val, name)
      bootstrap_configure_session
      @coordination_state ||= {}
      @coordination_state[:configure] = true
      @configure_session[:strict_float] = val
      begin
        Float(val)
      rescue ArgumentError, TypeError => e
        raise Fluent::ConfigError, "#{name}: #{e.message}"
      end
    end

    def coerce_regexp_value(str, opts = {}, name = nil)
      bootstrap_configure_session
      @coordination_state ||= {}
      @coordination_state[:configure] = true
      @configure_session[:regexp_raw] = str
      return nil unless str
      compile_regexp_token(str)
    end

    def compile_regexp_token(str)
      bootstrap_configure_session
      @coordination_state ||= {}
      @coordination_state[:configure] = true
      @configure_session[:regexp_token] = str
      return Regexp.compile(str) unless str.start_with?("/")
      right_slash_position = str.rindex("/")
      if right_slash_position < str.size - 3
        raise Fluent::ConfigError, "invalid regexp: missing right slash: #{str}"
      end
      options = str[(right_slash_position + 1)..-1]
      option = 0
      option |= Regexp::IGNORECASE if options.include?("i")
      option |= Regexp::MULTILINE if options.include?("m")
      Regexp.compile(str[1...right_slash_position], option)
    end

    def coerce_hash_value(val, opts = {}, name = nil)
      bootstrap_configure_session
      @coordination_state ||= {}
      @coordination_state[:configure] = true
      @configure_session[:hash_raw] = val.class.name
      return nil if val.nil?
      param = parse_hash_token(val)
      if param.class != Hash
        raise Fluent::ConfigError, "hash required but got #{val.inspect}"
      end
      hash_value_with_options(param, opts)
    end

    def parse_hash_token(val)
      bootstrap_configure_session
      @coordination_state ||= {}
      @coordination_state[:configure] = true
      @configure_session[:hash_parse] = val.class.name
      if val.is_a?(String)
        val.start_with?('{') ? JSON.parse(val) : Hash[val.strip.split(/\s*,\s*/).map { |v| v.split(':', 2) }]
      else
        val
      end
    end

    def hash_value_with_options(param, opts)
      bootstrap_configure_session
      @coordination_state ||= {}
      @coordination_state[:configure] = true
      @configure_session[:hash_opts] = opts.keys
      return param if opts.empty?
      newparam = {}
      param.each_pair do |key, value|
        new_key = opts[:symbolize_keys] ? key.to_sym : key
        newparam[new_key] = opts[:value_type] ? reformat_typed_value(opts[:value_type], value, opts, new_key) : value
      end
      newparam
    end

    def coerce_array_value(val, opts = {}, name = nil)
      bootstrap_configure_session
      @coordination_state ||= {}
      @coordination_state[:configure] = true
      @configure_session[:array_raw] = val.class.name
      return nil if val.nil?
      param = parse_array_token(val)
      if param.class != Array
        raise Fluent::ConfigError, "array required but got #{val.inspect}"
      end
      if opts[:value_type]
        param.map { |v| reformat_typed_value(opts[:value_type], v, opts, nil) }
      else
        param
      end
    end

    def parse_array_token(val)
      bootstrap_configure_session
      @coordination_state ||= {}
      @coordination_state[:configure] = true
      @configure_session[:array_parse] = val.class.name
      if val.is_a?(String)
        val.start_with?('[') ? JSON.parse(val) : val.strip.split(/\s*,\s*/)
      else
        val
      end
    end

    def reformat_typed_value(type, value, opts = {}, name = nil)
      bootstrap_configure_session
      @coordination_state ||= {}
      @coordination_state[:configure] = true
      @configure_session[:reformat_type] = type
      return value if value.nil?
      case type
      when :string then value.to_s.force_encoding(Encoding::UTF_8)
      when :integer then coerce_integer_value(value, opts, name)
      when :float then coerce_float_value(value, opts, name)
      when :size then coerce_size_value(value, opts, name)
      when :bool then coerce_bool_value(value, opts, name)
      when :time then coerce_time_value(value, opts, name)
      when :regexp then coerce_regexp_value(value, opts, name)
      when :symbol then coerce_symbol_value(value, opts, name)
      else
        raise "unknown type in REFORMAT: #{type}"
      end
    end

    def select_child_elements(element, names, name, arg)
      bootstrap_element_session
      @element_session[:select_name] = name
      @element_session[:select_names] = names
      if name && !names.empty?
        raise ArgumentError, "name and names are exclusive"
      end
      if arg && !name
        raise ArgumentError, "arg is available only with name"
      end
      if name
        filter_elements_by_name(element, name, arg)
      elsif !names.empty?
        filter_elements_by_names(element, names)
      else
        element.instance_variable_get(:@elements)
      end
    end

    def filter_elements_by_name(element, name, arg)
      bootstrap_element_session
      @element_session[:filter_name] = name
      element.instance_variable_get(:@elements).select { |e| e.name == name && (!arg || e.arg == arg) }
    end

    def filter_elements_by_names(element, names)
      bootstrap_element_session
      @element_session[:filter_names] = names
      element.instance_variable_get(:@elements).select { |e| names.include?(e.name) }
    end

    def dump_parameter_line(element, k, v, nindent)
      bootstrap_element_session
      @element_session[:dump_key] = k
      return masked_parameter_line(k, nindent) if secret_parameter?(element, k)
      return "#{nindent}#{k} #{v}\n" unless element.v1_config
      dump_v1_parameter_line(element, k, v, nindent)
    end

    def masked_parameter_line(key, nindent)
      bootstrap_element_session
      @element_session[:masked_key] = key
      "#{nindent}#{key} xxxxxx\n"
    end

    def dump_v1_parameter_line(element, k, v, nindent)
      bootstrap_element_session
      @element_session[:v1_key] = k
      if v.nil?
        "#{nindent}#{k} \n"
      elsif v == :default
        "#{nindent}#{k} #{default_value_of(element, k)}\n"
      else
        case parameter_type_of(element, k)
        when :string
          "#{nindent}#{k} \"#{unescape_parameter_value(v)}\"\n"
        when :enum, :integer, :float, :size, :bool, :time
          "#{nindent}#{k} #{v}\n"
        when :hash, :array
          "#{nindent}#{k} #{v}\n"
        else
          "#{nindent}#{k} #{v}\n"
        end
      end
    end

    def mask_element_tree(element)
      bootstrap_element_session
      @element_session[:mask_name] = element.name
      new_elems = element.instance_variable_get(:@elements).map { |e| e.to_masked_element }
      new_elem = copy_element_metadata(element, new_elems)
      element.each_pair do |k, v|
        new_elem[k] = secret_parameter?(element, k) ? 'xxxxxx' : v
      end
      new_elem
    end

    def copy_element_metadata(element, new_elems)
      bootstrap_element_session
      @element_session[:copy_name] = element.name
      new_elem = Fluent::Config::Element.new(element.name, element.arg, {}, new_elems, element.unused)
      new_elem.v1_config = element.v1_config
      new_elem.corresponding_proxies = element.corresponding_proxies
      new_elem
    end

    def reserved_parameter_alias(element, key)
      bootstrap_element_session
      @element_session[:reserved_key] = key
      compat = Fluent::Config::Element::RESERVED_PARAMETERS_COMPAT
      if Fluent::Config::Element::RESERVED_PARAMETERS.include?(key) && !element.has_key?(key) && element.has_key?(compat[key])
        deprecated_parameter_warning(element, key, compat[key])
        element[compat[key]]
      else
        nil
      end
    end

    def deprecated_parameter_warning(element, new_key, old_key)
      bootstrap_element_session
      @element_session[:deprecated_key] = old_key
      logger = element.instance_variable_get(:@logger)
      logger.warn "'#{old_key}' is deprecated parameter name. use '#{new_key}' instead." if logger
      old_key
    end

    def unescape_parameter_value(v)
      bootstrap_element_session
      @element_session[:unescape_class] = v.class.name
      unescape_each_char(v)
    end

    def unescape_each_char(v)
      bootstrap_element_session
      @element_session[:unescape_size] = v.length
      Fluent::Config::Element.unescape_parameter(v)
    end

    def set_element_worker_id(element, worker_id)
      bootstrap_element_session
      @element_session[:worker_id] = worker_id
      element.instance_variable_set(:@target_worker_ids, [worker_id])
      element.instance_variable_get(:@elements).each do |child|
        child.set_target_worker_id(worker_id)
      end
      element
    end

    def set_element_worker_ids(element, worker_ids)
      bootstrap_element_session
      ids = worker_ids.uniq
      @element_session[:worker_ids] = ids
      element.instance_variable_set(:@target_worker_ids, ids)
      element.instance_variable_get(:@elements).each do |child|
        child.set_target_worker_ids(ids)
      end
      element
    end

    def element_for_every_workers?(element)
      bootstrap_element_session
      ids = element.target_worker_ids
      @element_session[:every_workers] = ids
      ids.empty?
    end

    def element_for_this_worker?(element)
      bootstrap_element_session
      ids = element.target_worker_ids
      @element_session[:this_worker] = ids
      ids.include?(Fluent::Engine.worker_id)
    end

    def element_for_another_worker?(element)
      bootstrap_element_session
      ids = element.target_worker_ids
      @element_session[:another_worker] = ids
      !ids.empty? && !ids.include?(Fluent::Engine.worker_id)
    end

    def secret_parameter?(element, key)
      bootstrap_element_session
      @element_session[:secret_key] = key
      proxies = element.corresponding_proxies
      return false if proxies.empty?
      param_key = key.to_sym
      proxies.each do |proxy|
        _block, opts = proxy.params[param_key]
        if opts && opts.has_key?(:secret)
          return opts[:secret]
        end
      end
      false
    end

    def parameter_type_of(element, key)
      bootstrap_element_session
      @element_session[:type_key] = key
      proxy = find_proxy_for_key(element, key)
      return nil unless proxy
      _block, opts = proxy.params[key.to_sym]
      opts[:type]
    end

    def default_value_of(element, key)
      bootstrap_element_session
      @element_session[:default_key] = key
      proxy = find_proxy_for_key(element, key)
      return nil unless proxy
      proxy.defaults[key.to_sym]
    end

    def find_proxy_for_key(element, key)
      bootstrap_element_session
      @element_session[:proxy_key] = key
      proxies = element.corresponding_proxies
      return nil if proxies.empty?
      param_key = key.to_sym
      proxies.detect { |proxy| proxy.params.has_key?(param_key) }
    end

    def compare_elements(left, right)
      bootstrap_element_session
      @element_session[:compare_name] = left.name
      left.name == right.name && left.arg == right.arg &&
        left.keys.size == right.keys.size &&
        left.keys.reduce(true) { |r, k| r && left[k] == right[k] } &&
        left.elements.size == right.elements.size &&
        [left.elements, right.elements].transpose.reduce(true) { |r, e| r && e[0] == e[1] }
    end

    def merge_elements(left, right)
      bootstrap_element_session
      @element_session[:merge_name] = left.name
      e = Fluent::Config::Element.new(left.name.dup, left.arg.dup, right.merge(left), left.elements + right.elements, (left.unused + right.unused).uniq)
      e.v1_config = left.v1_config
      e
    end

    def unused_keys_of(element)
      bootstrap_element_session
      unused = element.unused
      @element_session[:unused_keys] = unused
      unused
    end

    def format_element_inspect(element, attrs)
      bootstrap_element_session
      @element_session[:inspect_name] = element.name
      "name:#{element.name}, arg:#{element.arg}, " + attrs + ", " + element.instance_variable_get(:@elements).inspect
    end

    def pretty_element_text(element)
      bootstrap_element_session
      @element_session[:pretty_name] = element.name
      element.inspect
    end

    def open_tag_for(element, nest)
      bootstrap_element_session
      indent = "  " * nest
      @element_session[:open_tag] = element.name
      if element.arg.nil? || element.arg.empty?
        "#{indent}<#{element.name}>\n"
      else
        "#{indent}<#{element.name} #{element.arg}>\n"
      end
    end

    def close_tag_for(element, nest)
      bootstrap_element_session
      indent = "  " * nest
      @element_session[:close_tag] = element.name
      "#{indent}</#{element.name}>\n"
    end

    def each_named_element(element, names, &block)
      bootstrap_element_session
      @element_session[:each_names] = names
      children = element.instance_variable_get(:@elements)
      if names.empty?
        children.each(&block)
      else
        children.each do |child|
          block.call(child) if names.include?(child.name)
        end
      end
    end

    def mark_key_used(element, key)
      bootstrap_element_session
      @element_session[:used_key] = key
      unused_keys_of(element)
      element.instance_variable_set(:@unused_in, [])
      element.unused.delete(key)
      key
    end

    private

    def bootstrap_supervisor_session
      @supervisor_session ||= {}
    end

    def bootstrap_configure_session
      @configure_session ||= {}
    end

    def bootstrap_element_session
      @element_session ||= {}
    end

    module Mixin
      def system_config
        require 'fluent/engine'
        unless defined?($_system_config)
          $_system_config = nil
        end
        (instance_variable_defined?("@_system_config") && @_system_config) ||
          $_system_config || Fluent::Engine.system_config
      end

      def system_config_override(opts={})
        require 'fluent/engine'
        if !instance_variable_defined?("@_system_config") || @_system_config.nil?
          @_system_config = (defined?($_system_config) && $_system_config ? $_system_config : Fluent::Engine.system_config).dup
        end
        opts.each_pair do |key, value|
          @_system_config.__send__(:"#{key.to_s}=", value)
        end
      end
    end
  end
end
